mapper.insert:
INSERT INTO  /* com.seinfo.protoA.util.token.TokenMapper.insertMifleGroup */
	seinfo_mfile_group
(
	mfile_group_id, mfile_info_id, reg_dt, reg_user_id
) VALUES (
	 #{mfileGrpId}
	,#{mfileInfoId}
	,now()
	,#{regUserId}
) ON DUPLICATE KEY UPDATE
    reg_dt = now()

INSERT INTO  /* com.seinfo.protoA.util.token.TokenMapper.insertMfileList */
	seinfo_mfile_list
(
	mfile_id, mfile_nm, mfile_path, mfile_type, mfile_status, mfile_size, mfile_group_id, reg_dt, reg_user_id
) VALUES (
	 #{mfileId}
	,#{mfileNm}
	,#{mfilePath}
	,#{mfileType}
	,#{mfileStatus}
	,#{mfileSize}
	,#{mfileGrpId}
	,now()
	,#{regUserId}
)

mapper.update:
UPDATE /* com.seinfo.protoA.util.token.TokenMapper.updateMfileList */
	 seinfo_mfile_list
  SET
     mfile_status = #{mfileStatus}
	,mod_dt = #{modDt}
	,mod_user_id = #{modUserId}
WHERE
    mfile_id = #{mfileId}

mapper.select:
SELECT /* com.seinfo.seinfomationA.component.file.mapper.selectMfileList */
	mfile_id, mfile_nm, mfile_path, mfile_type, mfile_status, mfile_group_id
FROM seinfo_mfile_list


		AND mfile_group_id = #{mfileGrpId}


		AND mfile_id = #{mfileId}


		AND mfile_status = #{mfileStatus}



	LIMIT 0, 5

SELECT /* com.seinfo.protoA.component.file.mapper.selectMfilePath */
	mfile_path
FROM seinfo_mfile_list
WHERE mfile_group_id = #{fileGrpId}
AND mfile_id = #{fileId}

