INSERT INTO  /* com.seinfo.protoA.util.token.TokenMapper.insertMifleGroup */
	seinfo_mfile_down
(
	mfile_down_id
	, mfile_down_yn
	, mfile_down_type
	, mfile_down_path
	, mfile_id
    , mfile_group_id
	, mfile_nm
	, reg_dt
	, reg_user_id
) VALUES (
	#{mfileDownId}
	, 'N'
	, #{mfileDownType}
	, #{mfileDownPath}
	, #{mfileId}
	, #{mfileGroupId}
	, #{mfileNm}
	, now()
	, #{regUserId}
)
